# Generated by scripts/publish.py for 0.1.0-alpha.1.
class MayiCli < Formula
  desc "Use secrets and website logins in commands without seeing them"
  homepage "https://github.com/aminehmida/mayi"
  version "0.1.0-alpha.1"

  # The release files are in a private repository, so they are fetched
  # through the GitHub API with a token that can read it.
  # Homebrew runs this with a reduced PATH, so gh is looked up in the
  # caller's own.
  token = ENV.fetch("HOMEBREW_GITHUB_API_TOKEN", "").strip
  if token.empty? && (gh = which("gh", ORIGINAL_PATHS))
    token = ::Utils.popen_read(gh.to_s, "auth", "token", "--user", "aminehmida").strip
  end
  headers = ["Accept: application/octet-stream", "Authorization: Bearer #{token}"]

  on_macos do
    depends_on arch: :arm64
    url "https://api.github.com/repos/aminehmida/mayi/releases/assets/750507295", headers: headers
    sha256 "56b14591511e9b79ba5865d26f454ac17401ac9727634ab7983fd8558917e4d3"
  end
  on_linux do
    on_intel do
      url "https://api.github.com/repos/aminehmida/mayi/releases/assets/750507331", headers: headers
      sha256 "5e81b3defb27f6128cac84c4d2f3af9adc02eafdf13651b9eec255cb36112af3"
    end
    on_arm do
      url "https://api.github.com/repos/aminehmida/mayi/releases/assets/750507294", headers: headers
      sha256 "fb27c18caf96af80853893676bd500c4c58ec20b998c576f6df3158ff1cde7aa"
    end
  end

  def install
    bin.install "mayi"
    pkgshare.install "skill"
  end

  def caveats
    <<~EOS
      This is the requester only. It asks a vault device (the Mayi app on a Mac
      or an Android phone) for secrets; pair it with `mayi pair TOKEN`.

      The agent skill is in #{opt_pkgshare}/skill/mayi. For Claude Code:
        cp -R #{opt_pkgshare}/skill/mayi ~/.claude/skills/
    EOS
  end

  test do
    assert_match version.to_s, shell_output("#{bin}/mayi --version")
  end
end
